solution.code:
public class Main {
    public static void main(String[] args) {
        int[] counts = new int[26];
        for (char c : "mississippi".toCharArray()) {
            counts[c - 'a']++;
        }
        for (int i = 0; i < 26; i++) {
            if (counts[i] > 0) {
                System.out.println((char) ('a' + i) + ": " + counts[i]);
            }
        }
    }
}
